1	"use client";
2	import { memo, useRef, useState, useEffect } from "react";
3	import {
4	  Handle,
5	  Position,
6	  useStore,
7	  type Node,
8	  type NodeProps,
9	} from "@xyflow/react";
10	import ReactMarkdown from "react-markdown";
11	import remarkGfm from "remark-gfm";
12	import rehypeRaw from "rehype-raw";
13	import rehypeHighlight from "rehype-highlight";
14	import { useSessionStore } from "@/stores/sessionStore";
15	import {
16	  subscribeStream,
17	  getStreamPending,
18	  thinkingChannel,
19	} from "@/lib/stream-bus";
20	import { COMPACT_ZOOM_THRESHOLD, PEEK_CARD_HEIGHT } from "@/lib/layout";
21	import { MD_COMPONENTS, MD_URL_TRANSFORM } from "@/lib/md-components";
22	import { AttachmentPreview } from "./AttachmentPreview";
23	import { formatTokens } from "@/lib/format-tokens";
24	import { injectMarks, clearMarks, type MarkSpec } from "@/lib/dom-mark-injector";
25	import type { ChatNode as ChatNodeData, ToolCall } from "@/lib/types";
26	import {
27	  buildToolTree,
28	  countToolTree,
29	  subagentLabel,
30	  walkToolTree,
31	} from "@/lib/tool-tree";
32	import { CollapseChip } from "./CollapseChip";
33	import { DeleteCardButton } from "./DeleteCardButton";
34	import { SupersededErrorNotice } from "./SupersededErrorNotice";
35	import { CopyButton } from "./CopyButton";
36	import { isSendCombo, sendHint } from "@/lib/send-key";
37	import { useSkillSuggestions } from "@/hooks/useSkillSuggestions";
38	import { useSlashNav } from "@/hooks/useSlashNav";
39	import { SkillPickerList } from "./SkillPickerList";
40	import { ZoneEditor } from "./ZoneEditor";
41	import { EmptyResponseNotice } from "./EmptyResponseNotice";
42	
43	// Plugin arrays at module scope so identity is stable across renders.
44	const REMARK_PLUGINS = [remarkGfm];
45	const REHYPE_FULL = [rehypeRaw, rehypeHighlight];
46	
47	export type ChildAnchor = { text: string; childId: string };
48	
49	export type ChatFlowNode = Node<
50	  {
51	    node: ChatNodeData;
52	    isActive: boolean;
53	    childAnchors: ChildAnchor[];
54	    // 1-based session-scoped index (createdAt order). 0 if unknown.
55	    index: number;
56	    // Total descendants (direct + indirect). Drives the "▶/▼ N" chip;
57	    // 0 means the node is a leaf and the chip is suppressed.
58	    descendantCount: number;
59	    // Whether this node's subtree is currently folded.
60	    collapsed: boolean;
61	    // Peek: render this node's full card in place on the canvas (instead of
62	    // the compact topic card) without switching to the linear reader.
63	    isPeeked: boolean;
64	    onTogglePeek: (id: string) => void;
65	  },
66	  "chat"
67	>;
68	
69	function ChatNodeImpl({ data }: NodeProps<ChatFlowNode>) {
70	  const n = data.node;
71	  const isStreaming = n.status === "streaming";
72	  const isError = n.status === "error";
73	  const isActive = data.isActive;
74	  const indexLabel = data.index ? `#${data.index}` : "";
75	  // Only "done" nodes can be unread — streaming / error states have their
76	  // own visual treatment (indigo border / error states).
77	  const isUnread = n.status === "done" && !n.readAt;
78	  // ReactFlow viewport zoom: transform = [x, y, zoom]. Selector returns a
79	  // boolean so re-renders only fire when crossing the threshold.
80	  const isCompact = useStore((s) => s.transform[2] < COMPACT_ZOOM_THRESHOLD);
81	
82	  const setActiveNode = useSessionStore((s) => s.setActiveNode);
83	  const setViewMode = useSessionStore((s) => s.setViewMode);
84	  const retryNode = useSessionStore((s) => s.retryNode);
85	  const toggleCollapse = useSessionStore((s) => s.toggleCollapse);
86	  const showCollapseChip = data.descendantCount > 0;
87	  const onMarkClick = (e: React.MouseEvent) => {
88	    const target = (e.target as HTMLElement).closest("[data-child-id]");
89	    if (!target) return;
90	    const childId = target.getAttribute("data-child-id");
91	    if (!childId) return;
92	    e.preventDefault();
93	    e.stopPropagation();
94	    e.nativeEvent.stopImmediatePropagation();
95	    // ReactFlow's onNodeClick fires on the same click and would override
96	    // activeNodeId to the parent's id. Defer to win the race.
97	    window.setTimeout(() => setActiveNode(childId), 0);
98	  };
99	  // #7: reading happens in the linear thread anchored at this node (the old
100	  // fullscreen single-card reader is retired).
101	  const goRead = (e: React.MouseEvent) => {
102	    e.stopPropagation();
103	    setActiveNode(n.id);
104	    setViewMode("linear");
105	  };
106	  // While streaming, deltas land on the stream-bus (not in React state).
107	  // We attach a textContent-only sink to a <pre> ref so each token is one
108	  // tiny DOM mutation, no React render, no ReactFlow diff. When the stream
109	  // finishes, sessionStore commits the full text and React re-renders this
110	  // node once with the full ReactMarkdown pipeline.
111	  const streamRef = useRef<HTMLDivElement>(null);
112	  useEffect(() => {
113	    if (!isStreaming) return;
114	    const el = streamRef.current;
115	    if (!el) return;
116	    el.textContent = n.response + getStreamPending(n.id);
117	    return subscribeStream(n.id, (delta) => {
118	      el.textContent = (el.textContent ?? "") + delta;
119	    });
120	    // n.response intentionally excluded from deps: it doesn't change while
121	    // streaming (deltas bypass the store), and re-running this effect on
122	    // every render would clobber the DOM-direct text.
123	    // eslint-disable-next-line react-hooks/exhaustive-deps
124	  }, [isStreaming, n.id]);
125	
126	  // Extended thinking indicator: claude thinks BEFORE it answers (minutes
127	  // under high effort), during which streamRef stays empty and the card used
128	  // to look dead. DOM-direct toggle (same no-React-render discipline as
129	  // streamRef): visible while thinking deltas flow and no text has arrived.
130	  const thinkingRef = useRef<HTMLDivElement>(null);
131	  useEffect(() => {
132	    if (!isStreaming) return;
133	    const el = thinkingRef.current;
134	    if (!el) return;
135	    const sync = () => {
136	      const hasText =
137	        n.response.length > 0 || getStreamPending(n.id).length > 0;
138	      const hasThinking = getStreamPending(thinkingChannel(n.id)).length > 0;
139	      el.style.display = hasThinking && !hasText ? "flex" : "none";
140	    };
141	    sync();
142	    const unsubThinking = subscribeStream(thinkingChannel(n.id), sync);
143	    const unsubText = subscribeStream(n.id, sync);
144	    return () => {
145	      unsubThinking();
146	      unsubText();
147	    };
148	    // n.response excluded for the same reason as the effect above.
149	    // eslint-disable-next-line react-hooks/exhaustive-deps
150	  }, [isStreaming, n.id]);
151	
152	  // Inject child <mark> on the rendered markdown DOM. Same approach as
153	  // NodeFullView's ResponseBody — see lib/dom-mark-injector.ts.
154	  const bodyRef = useRef<HTMLDivElement>(null);
155	  useEffect(() => {
156	    if (isStreaming) return;
157	    const root = bodyRef.current;
158	    if (!root) return;
159	    clearMarks(root);
160	    if (data.childAnchors.length) {
161	      const specs: MarkSpec[] = [
162	        {
163	          dataKey: "childId",
164	          anchors: data.childAnchors.map((a) => ({
165	            text: a.text,
166	            id: a.childId,
167	          })),
168	        },
169	      ];
170	      injectMarks(root, specs);
171	    }
172	    return () => {
173	      if (root) clearMarks(root);
174	    };
175	  }, [isStreaming, n.response, data.childAnchors]);
176	
177	  const labelText = n.topicLabel ?? truncate(n.question, 14);
178	  // 错误降级：有后代 = 用户已在后续节点续跑/绕过，错误不再是"待处理"状态。
179	  const errorSuperseded = isError && data.descendantCount > 0;
180	  // Compact mode: streaming / fresh-error nodes always render full so user
181	  // can see progress and act. Done nodes — and superseded errors, whose
182	  // loud treatment has expired — collapse to a topic card at low zoom.
183	  const showCompact =
184	    isCompact &&
185	    !isStreaming &&
186	    (!isError || errorSuperseded) &&
187	    !data.isPeeked;
188	
189	  if (showCompact) {
190	    return (
191	      <div
192	        className={`group relative nopan w-[280px] rounded-card bg-surface cursor-pointer transition-all duration-200 ring-1 shadow-[0_1px_2px_rgba(28,25,23,0.04),0_6px_20px_-6px_rgba(28,25,23,0.10)] hover:shadow-[0_2px_4px_rgba(28,25,23,0.05),0_14px_30px_-8px_rgba(28,25,23,0.18)] hover:-translate-y-px ${
193	          isActive
194	            ? "ring-2 ring-accent/80"
195	            : isUnread
196	              ? "ring-unread-line/80"
197	              : "ring-line/80 hover:ring-line-strong"
198	        }`}
199	        onClick={goRead}
200	        title={n.question}
201	      >
202	        <Handle type="target" position={Position.Top} />
203	        <DeleteCardButton nodeId={n.id} />
204	        {/* Peek toggle: a hover-only corner chip matching DeleteCardButton's
205	            circle, parked just left of the ✕ — same visual language, no
206	            content-row clutter. */}
207	        <button
208	          type="button"
209	          onClick={(e) => {
210	            e.stopPropagation();
211	            data.onTogglePeek(n.id);
212	          }}
213	          title="展开预览（留在画布）"
214	          aria-label="展开预览"
215	          className="absolute -top-2 right-4 z-10 w-5 h-5 rounded-full border bg-surface border-line-strong text-ink-muted shadow-raise opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 hover:bg-ink hover:text-ink-inverse hover:border-ink transition-opacity flex items-center justify-center"
216	        >
217	          <svg
218	            width="10"
219	            height="10"
220	            viewBox="0 0 24 24"
221	            fill="none"
222	            stroke="currentColor"
223	            strokeWidth="2.6"
224	            strokeLinecap="round"
225	            strokeLinejoin="round"
226	            aria-hidden
227	          >
228	            <path d="M6 9l6 6 6-6" />
229	          </svg>
230	        </button>
231	        {showCollapseChip && (
232	          <CollapseChip
233	            collapsed={data.collapsed}
