32	const REHYPE_FULL = [rehypeRaw, rehypeHighlight];
33	// 流式期间只做最小 rehype：rehypeRaw 跳过（半行 HTML 标签既浪费又可能抛错），
34	// rehypeHighlight 也跳过——它会在每一帧对**整段** response 重跑语法高亮，
35	// 几百 KB 的长回复能把主线程卡死，正是「tab 点不开」的主因。高亮只在 done
36	// 态（REHYPE_FULL）跑一次，性价比远高于边流式边高亮。
37	const REHYPE_STREAMING: typeof REHYPE_FULL = [];
38	
39	// #7: the single "turn" reading/interaction surface, shared by every place a
40	// node is read in full (the linear thread is the only consumer today — the
41	// old NodeFullView duplicated all of this and has been retired). Carries the
42	// complete capability set: parent-anchor jump banner, editable question,
43	// tool-call panel, mark-injected markdown body with live streaming, the
44	// action row (CLI resume / regenerate / card image / copy), generated files,
45	// and the paused-interaction form.
46	// React.memo：线性 thread 订阅整个 `nodes` 对象，流式期间每个 tool_call
47	// 事件（合批后仍是每帧一次）都会让父组件重渲。未变的节点（同引用）直接跳
48	// 过——避免 15 张已完成卡片每次都重跑 REHYPE_FULL 语法高亮。只有正在流式
49	// 的节点引用每帧更新，正常重渲（且流式态已不跑高亮，成本低）。
50	export const TurnCard = memo(function TurnCard({ node }: { node: ChatNode }) {
51	  const jumpToParentAtAnchor = useSessionStore((s) => s.jumpToParentAtAnchor);
52	  const hasParent = useSessionStore((s) =>
53	    Boolean(node.parentId && s.nodes[node.parentId]),
54	  );
55	
56	  if (node.kind === "reference") {
57	    return <ReferenceFullBody key={node.id} node={node} />;
58	  }
59	
60	  return (
61	    <>
62	      {node.parentAnchor && hasParent && (
63	        <button
64	          onClick={() => jumpToParentAtAnchor(node.parentId!, node.id)}
65	          className="w-full text-left mb-3 px-3 py-2 rounded-lg bg-fork-muted border border-fork-line text-ui text-fork-ink active:scale-[0.99] transition-transform shadow-raise hover:bg-fork-line/25"
66	          title="回到父节点的引用处 (B)"
67	        >
68	          <span className="text-fork mr-1">↳</span>
69	          从「
70	          <span className="font-medium">
71	            {truncate(node.parentAnchor.selectedText, 60)}
72	          </span>
73	          」分叉
74	          <span className="ml-1.5 text-fork-ink/70">
75	            · 点击或按
76	            <kbd className="mx-1 px-1 py-px rounded bg-fork-line/40 border border-fork-line font-mono text-nano">
77	              B
78	            </kbd>
79	            回到引用处
80	          </span>
81	        </button>
82	      )}
83	      <QuestionBlock
84	        nodeId={node.id}
85	        question={node.question}
86	        attachments={node.attachments}
87	      />
88	      {/* One chronological timeline of everything the turn did — delegated
89	          work nests under the call that spawned it rather than being pulled
90	          out into a parallel panel. */}
91	      <ToolTimeline
92	        toolCalls={node.toolCalls}
93	        live={node.status === "streaming"}
94	      />
95	      {/* key={node.id} forces a fresh ResponseBody fiber per node: the
96	          imperative <mark> injection inside react-markdown's output diverges
97	          from React's virtual tree, so when the node prop changes in-place
98	          React's reconciler tries to removeChild against DOM that was
99	          re-parented under our marks and throws NotFoundError. Unmounting
100	          cleanly lets the cleanup clearMarks() run before React touches the
101	          DOM. */}
102	      <ResponseBody key={node.id} node={node} />
103	      {/* A路③: when this node's run is paused on an interactive tool, render
104	          the answer form below the response so the user can reply in place
105	          and the model continues. */}
106	      {node.pendingInteraction && (
107	        <InteractionForm
108	          nodeId={node.id}
109	          interaction={node.pendingInteraction}
110	        />
111	      )}
112	    </>
113	  );
114	});
115	
116	// D5: regenerate the same question as a NEW sibling (a second "version"),
117	// rather than overwriting in place like retry. The branch entries in the
118	// thread then let the user compare the variants side by side.
119	function RegenerateVariantButton({
120	  nodeId,
121	  question,
122	}: {
123	  nodeId: string;
124	  question: string;
125	}) {
126	  const editNode = useSessionStore((s) => s.editNode);
127	  return (
128	    <Button
129	      type="button"
130	      variant="secondary"
131	      size="sm"
132	      onClick={(e) => {
133	        e.stopPropagation();
134	        editNode(nodeId, question);
135	      }}
136	      title="用相同问题再生成一个版本（新建兄弟节点，可在分支列表对比）"
137	      className="nodrag"
138	    >
139	      ↻ 再答一版
140	    </Button>
141	  );
142	}
143	
144	function QuestionBlock({
145	  nodeId,
146	  question,
147	  attachments,
148	}: {
149	  nodeId: string;
150	  question: string;
151	  attachments: NodeAttachment[];
152	}) {
153	  const editNode = useSessionStore((s) => s.editNode);
154	  const sendKey = useSessionStore((s) => s.sendKey);
155	  const [editing, setEditing] = useState(false);
156	  const [text, setText] = useState(question);
157	
158	  const submit = () => {
159	    const t = text.trim();
160	    if (!t) return;
161	    setEditing(false);
162	    editNode(nodeId, t);
163	  };
164	  const cancel = () => {
165	    setEditing(false);
166	    setText(question);
167	  };
168	
169	  if (editing) {
170	    return (
171	      <div className="bg-accent-muted border border-accent-line rounded-lg px-4 py-3 mb-4">
172	        <textarea
173	          value={text}
174	          autoFocus
175	          onChange={(e) => setText(e.target.value)}
176	          onKeyDown={(e) => {
177	            if (isSendCombo(e, sendKey)) {
178	              e.preventDefault();
179	              submit();
180	            } else if (e.key === "Escape") {
181	              e.preventDefault();
182	              cancel();
183	            }
184	          }}
185	          rows={3}
186	          className="w-full resize-none px-3 py-2 rounded-field border border-accent-line bg-surface text-reading text-ink-strong outline-none focus:border-accent leading-relaxed"
187	        />
188	        <div className="flex items-center justify-between gap-2 mt-2">
189	          <span className="text-label text-ink-faint min-w-0 truncate">
190	            改问法会新建一个分支，保留原问答（{sendHint(sendKey)}）
191	          </span>
192	          <div className="flex items-center gap-2 shrink-0">
193	            <Button variant="ghost" size="sm" onClick={cancel}>
194	              取消
195	            </Button>
196	            <Button
197	              variant="primary"
198	              size="sm"
199	              onClick={submit}
200	              disabled={!text.trim()}
201	            >
202	              ↻ 重问
203	            </Button>
204	          </div>
205	        </div>
206	      </div>
207	    );
208	  }
209	
210	  return (
211	    <div className="group bg-accent-muted border-l-[3px] border-l-accent rounded-lg px-4 py-3 mb-5 flex items-start gap-3">
212	      <div className="w-7 h-7 rounded-full bg-accent text-ink-inverse text-label flex items-center justify-center shrink-0 font-medium shadow-raise">
213	        你
214	      </div>
215	      <div className="flex-1 text-reading text-ink leading-relaxed pt-1 font-medium whitespace-pre-wrap break-words min-w-0">
216	        {question}
217	        {attachments.length > 0 && (
218	          <div className="mt-2 font-normal">
219	            <AttachmentPreview attachments={attachments} readOnly />
220	          </div>
221	        )}
222	      </div>
223	      <button
224	        onClick={() => {
225	          setText(question);
226	          setEditing(true);
227	        }}
228	        title="编辑问题（会新建一个分支重问）"
229	        aria-label="编辑问题"
230	        className="shrink-0 mt-0.5 w-7 h-7 flex items-center justify-center rounded-md text-ink-muted opacity-60 sm:opacity-0 group-hover:opacity-100 hover:bg-surface-raised hover:text-accent transition-opacity"
231	      >
232	        <svg
233	          width="14"
234	          height="14"
235	          viewBox="0 0 24 24"
236	          fill="none"
237	          stroke="currentColor"
238	          strokeWidth="2"
239	          strokeLinecap="round"
240	          strokeLinejoin="round"
241	          aria-hidden
242	        >
243	          <path d="M12 20h9" />
244	          <path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" />
245	        </svg>
246	      </button>
247	    </div>
248	  );
249	}
250	
251	// Dim auto-scrolling viewport for the live thinking stream. Pinned to the
252	// bottom as text grows (thinking is transient status, not reading material —
253	// following the tail beats preserving scroll position).
254	function ThinkingScroll({
255	  text,
256	  className,
257	}: {
258	  text: string;
259	  className?: string;
260	}) {
261	  const ref = useRef<HTMLDivElement>(null);
262	  useEffect(() => {
263	    const el = ref.current;
264	    if (el) el.scrollTop = el.scrollHeight;
265	  }, [text]);
266	  return (
267	    <div
268	      ref={ref}
269	      className={`max-h-36 overflow-y-auto whitespace-pre-wrap break-words text-ui leading-relaxed text-ink-faint ${className ?? ""}`}
270	    >
271	      {text}
272	    </div>
273	  );
274	}
275	
276	// S88：@提及的一次性外援标记。刻意只说「由 @提及的 Agent 作答」而不查名字 ——
277	// 节点只存 agent id，为一枚 chip 去 fetch 每个节点的 agent 名不值当，而且被删掉的
278	// agent 会让历史节点渲染出一片空白。语义（这轮不是主线人格答的）已经传达到了。
279	function MentionChip() {
280	  return (
281	    <div className="mb-2 inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-accent-muted text-accent-ink text-label">
282	      <span aria-hidden>🎭</span>
283	      <span>这一轮由 @提及的 Agent 单独作答（主线人格不变）</span>
284	    </div>
285	  );
286	}
287	
288	function ResponseBody({ node }: { node: ChatNode }) {
289	  const retryNode = useSessionStore((s) => s.retryNode);
290	  const bodyRef = useRef<HTMLDivElement>(null);
291	  const isStreaming = node.status === "streaming";
292	  const isError = node.status === "error";
293	  // 错误降级（见 SupersededErrorNotice）：有子节点 = 用户已续跑/绕过，
294	  // 红横幅降级为安静备注。boolean selector，仅在真假翻转时触发重渲染。
295	  const hasChildren = useSessionStore((s) => {
296	    for (const k in s.nodes) {
297	      if (s.nodes[k].parentId === node.id) return true;
298	    }
299	    return false;
300	  });
301	
302	  const { onMarkClick } = useMarkdownBodyMarks({
303	    bodyRef,
304	    nodeId: node.id,
305	    contentVersion: node.response,
306	    suspended: isStreaming,
307	  });
308	
309	  // A1: live markdown render while streaming. Accumulate deltas in a ref and
310	  // flush to state on requestAnimationFrame (coalescing token bursts to one
311	  // re-render per frame), then render through ReactMarkdown so code/lists/
312	  // tables format as they arrive — matching GPT/Claude. Affordable here
313	  // because turn cards live in a plain scroll list, not inside the ReactFlow
314	  // canvas (ChatNode deliberately keeps the textContent-direct sink there).
315	  const [liveText, setLiveText] = useState("");
316	  useEffect(() => {
317	    if (!isStreaming) return;
318	    let raf = 0;
319	    let buf = node.response + getStreamPending(node.id);
320	    setLiveText(buf);
321	    const flush = () => {
322	      raf = 0;
323	      setLiveText(buf);
324	    };
325	    const unsub = subscribeStream(node.id, (delta) => {
326	      buf += delta;
327	      if (!raf) raf = requestAnimationFrame(flush);
328	    });
329	    return () => {
330	      if (raf) cancelAnimationFrame(raf);
331	      unsub();
332	    };
333	    // eslint-disable-next-line react-hooks/exhaustive-deps
334	  }, [isStreaming, node.id]);
335	
336	  // Extended thinking: claude streams a thinking block BEFORE the text block
337	  // (minutes under high effort). Same rAF-coalesced bus subscription as the
338	  // text deltas, separate channel. Ephemeral — vanishes when the turn ends.
339	  const [liveThinking, setLiveThinking] = useState("");
340	  useEffect(() => {
341	    if (!isStreaming) {
342	      setLiveThinking("");
343	      return;
344	    }
345	    let raf = 0;
346	    let buf = getStreamPending(thinkingChannel(node.id));
347	    setLiveThinking(buf);
348	    const flush = () => {
349	      raf = 0;
350	      setLiveThinking(buf);
351	    };
352	    const unsub = subscribeStream(thinkingChannel(node.id), (delta) => {
353	      buf += delta;
354	      if (!raf) raf = requestAnimationFrame(flush);
355	    });
356	    return () => {
357	      if (raf) cancelAnimationFrame(raf);
358	      unsub();
359	    };
360	  }, [isStreaming, node.id]);
361	
362	  return (
363	    <div
364	      ref={bodyRef}
365	      data-chat-node-id={node.id}
366	      onClick={onMarkClick}
367	      className="md-body text-reading text-ink leading-relaxed"
368	    >
369	      {/* S88 @提及：这一轮是外援答的，标出来 —— 否则读者会以为主线人格变了。
370	          会话级人设（agentScope==='session'）刻意不挂 chip：每张卡都挂一枚是
371	          噪音，那个显示在 Header 的 ModeBadge 上。 */}
372	      {node.agentScope === "mention" && <MentionChip />}
373	      {isStreaming && liveThinking && (
374	        // The思考期 surface. While no answer text yet: an open dim panel with
375	        // the thinking stream (this is what used to look like a dead UI for
376	        // up to minutes). Once the answer starts: collapse to a <details>
377	        // (uncontrolled so a user toggle sticks). Gone entirely at done.
378	        liveText ? (
379	          <details className="mb-2">
380	            <summary className="cursor-pointer select-none text-ui text-ink-faint hover:text-ink-muted">
381	              🧠 思考过程（{liveThinking.length} 字）
382	            </summary>
383	            <ThinkingScroll text={liveThinking} className="mt-1" />
384	          </details>
385	        ) : (
386	          <div className="mb-2 rounded-md border border-line/70 bg-surface-muted/60 px-3 py-2">
387	            <div className="mb-1 flex items-center gap-1.5 text-ui text-ink-faint">
388	              <span className="w-1.5 h-1.5 rounded-full bg-accent animate-pulse" />
389	              思考中…
390	            </div>
391	            <ThinkingScroll text={liveThinking} />
392	          </div>
393	        )
394	      )}
395	      {isStreaming ? (
396	        liveText ? (
397	          <>
398	            <ReactMarkdown
399	              remarkPlugins={REMARK_PLUGINS}
400	              rehypePlugins={REHYPE_STREAMING}
401	              components={MD_COMPONENTS}
402	            urlTransform={MD_URL_TRANSFORM}
403	            >
404	              {liveText}
405	            </ReactMarkdown>
406	            <span className="streaming-cursor" />
407	          </>
408	        ) : liveThinking ? null : (
409	          // First token hasn't arrived yet — show an animated indicator
410	          // instead of a blank pane (the "no streaming" complaint).
411	          <div className="flex items-center gap-1.5 py-2 text-ink-faint">
412	            <Dots />
413	            <span className="ml-1.5 text-ui">正在生成…</span>
414	          </div>
415	        )
416	      ) : node.response ? (
417	        <>
418	          <ReactMarkdown
419	            remarkPlugins={REMARK_PLUGINS}
420	            rehypePlugins={REHYPE_FULL}
421	            components={MD_COMPONENTS}
422	            urlTransform={MD_URL_TRANSFORM}
423	          >
424	            {node.response}
425	          </ReactMarkdown>
426	          <div className="mt-3 flex justify-end gap-2">
427	            <CliResumeButton nodeId={node.id} />
428	            <RegenerateVariantButton nodeId={node.id} question={node.question} />
429	            <CardImageButton
430	              title={node.topicLabel ?? node.question}
431	              content={node.response}
432	            />
433	            <CopyButton
434	              text={node.response}
435	              label="复制全文"
436	              className="nodrag px-2.5 py-1 rounded border border-line text-ui text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
437	            />
438	          </div>
439	          <GeneratedFilesBar node={node} />
440	        </>
441	      ) : (
442	        <EmptyResponseNotice hasToolCalls={node.toolCalls.length > 0} />
443	      )}
444	      {isError && hasChildren && (
445	        <SupersededErrorNotice
446	          nodeId={node.id}
447	          errorMessage={node.errorMessage}
448	        />
449	      )}
450	      {isError &&
451	        !hasChildren &&
452	        (node.errorMessage === "aborted" ? (
453	          <div className="mt-3 p-2.5 bg-surface-muted border border-line rounded text-ink-muted text-ui flex items-start gap-2">
454	            <div className="flex-1">已停止生成</div>
455	            <Button
456	              variant="primary"
457	              size="sm"
458	              className="shrink-0"
459	              onClick={() => retryNode(node.id)}
460	            >
461	              ↻ 重新发送
462	            </Button>
463	          </div>
464	        ) : (
465	          <div className="mt-3 p-2.5 bg-danger-muted border border-danger-line rounded text-danger-ink text-ui flex items-start gap-2">
466	            <div className="flex-1">出错：{node.errorMessage}</div>
467	            <Button
468	              variant="danger"
469	              size="sm"
470	              className="shrink-0"
471	              onClick={() => retryNode(node.id)}
472	            >
473	              ↻ 重新生成
474	            </Button>
475	          </div>
476	        ))}
477	    </div>
478	  );
479	}
480	
481	function ReferenceFullBody({ node }: { node: ChatNode }) {
482	  const refreshReference = useSessionStore((s) => s.refreshReference);
483	  const abortStream = useSessionStore((s) => s.abortStream);
484	  const fetchProgress = useSessionStore((s) => s.fetchProgress[node.id]);
485	  const [refreshing, setRefreshing] = useState(false);
486	  const ref = node.reference;
487	  const isStreaming = node.status === "streaming";
488	  const bodyRef = useRef<HTMLDivElement>(null);
489	  const { onMarkClick } = useMarkdownBodyMarks({
490	    bodyRef,
491	    nodeId: node.id,
492	    contentVersion: ref?.contentMd ?? "",
493	    suspended: isStreaming,
494	  });
495	  if (!ref) {
496	    return (
497	      <div className="text-ink-faint italic text-sm">参考卡片数据缺失</div>
498	    );
499	  }
500	  const canRefresh = ref.sourceType === "url" && !isStreaming;
501	  const onRefresh = async () => {
502	    if (refreshing) return;
503	    setRefreshing(true);
504	    try {
505	      await refreshReference(node.id);
506	    } finally {
507	      setRefreshing(false);
508	    }
509	  };
510	
511	  return (
512	    <>
513	      <div
514	        className={`mb-4 px-4 py-3 rounded-lg border text-ui flex items-start gap-2.5 ${
515	          isStreaming
516	            ? "bg-accent-muted border-accent-line"
517	            : "bg-warn-muted border-warn-line"
518	        }`}
519	      >
520	        <span className="text-title leading-none mt-0.5" aria-hidden>
521	          {isStreaming ? "⏳" : refIcon(ref)}
522	        </span>
523	        <div className="flex-1 min-w-0">
524	          <div className="font-semibold text-ink-strong truncate">
525	            {node.topicLabel ?? "参考材料"}
526	          </div>
527	          {ref.sourceUri && (
528	            <a
529	              href={ref.sourceUri}
530	              target="_blank"
531	              rel="noreferrer"
532	              className={`block mt-0.5 truncate underline-offset-2 hover:underline ${
533	                isStreaming ? "text-accent-ink" : "text-warn-ink"
534	              }`}
535	              onClick={(e) => e.stopPropagation()}
536	            >
537	              {ref.sourceUri}
538	            </a>
539	          )}
540	          {ref.meta.fetchError && !isStreaming && (
541	            <div className="mt-1 text-danger-ink text-ui">
542	              ⚠️ 抓取失败：{ref.meta.fetchError}
543	            </div>
544	          )}
545	        </div>
546	        {isStreaming ? (
547	          <StopButton
548	            label="停止"
549	            onClick={() => abortStream(node.id)}
550	            className="shrink-0"
551	            title="停止抓取"
552	          />
553	        ) : (
554	          canRefresh && (
555	            <button
556	              onClick={onRefresh}
557	              disabled={refreshing}
558	              className="shrink-0 px-2 py-1 text-label rounded border border-warn-line text-warn-ink hover:bg-warn-line/25 active:scale-95 disabled:opacity-50 transition-colors"
559	              title="重新抓取"
560	            >
561	              {refreshing ? "抓取中…" : "↻ 刷新"}
562	            </button>
563	          )
564	        )}
565	      </div>
566	
567	      {isStreaming && (
568	        <div className="mb-4 px-4 py-3 rounded-lg bg-surface-muted border border-line">
569	          <div className="flex items-center gap-2 text-ui text-ink-muted">
570	            <span className="inline-block w-2 h-2 bg-accent rounded-full animate-pulse" />
571	            <span className="font-medium">{fetchProgress || "启动中…"}</span>
572	          </div>
573	          <div className="mt-2 text-label text-ink-faint leading-relaxed">
574	            claude 正在挑选并运行合适的 skill 抓取这个 URL。
575	            飞书 / YouTube / B站 等通常 5–60 秒，PDF / 大型文档可能更久。
576	            可以随时点上方"停止"取消。
577	          </div>
578	        </div>
579	      )}
580	
581	      <div
582	        ref={bodyRef}
583	        data-chat-node-id={node.id}
584	        onClick={onMarkClick}
585	        className="md-body text-reading text-ink leading-relaxed"
586	      >
587	        {ref.contentMd ? (
588	          <ReactMarkdown
589	            remarkPlugins={REMARK_PLUGINS}
590	            rehypePlugins={REHYPE_FULL}
591	            components={MD_COMPONENTS}
592	            urlTransform={MD_URL_TRANSFORM}
593	          >
594	            {ref.contentMd}
595	          </ReactMarkdown>
596	        ) : isStreaming ? null : (
597	          <div className="text-ink-faint italic text-sm">
598	            {ref.meta.fetchError
599	              ? "抓取失败，没有内容可显示。点上方刷新重试，或编辑后重新粘贴。"
600	              : "（没有正文）"}
601	          </div>
602	        )}
603	      </div>
604	    </>
605	  );
606	}
607	
608	function truncate(s: string, n: number) {
609	  return s.length > n ? s.slice(0, n) + "…" : s;
610	}
