2	import { useEffect, useMemo } from "react";
3	import { useSessionStore } from "@/stores/sessionStore";
4	import { injectMarks, clearMarks, type MarkSpec } from "@/lib/dom-mark-injector";
5	
6	// Shared between the qa ResponseBody and ReferenceFullBody (TurnCard) — both
7	// render markdown that may carry child anchors (qa kids forked from selection)
8	// and note anchors (excerpts captured from this node). The hook owns the
9	// imperative <mark> injection and the pendingScrollAnchor flash so neither
10	// call site has to duplicate ~80 lines of effect code.
11	//
12	// Caller must pass `key={node.id}` on the rendered body (or a parent
13	// component that owns the bodyRef DOM) — this avoids the React reconciler
14	// tripping over the manually-injected <mark> wrappers when the same fiber's
15	// content swaps to a new node. See the bug postmortem in
16	// NotFoundError-removeChild diagnosis.
17	export function useMarkdownBodyMarks(opts: {
18	  bodyRef: React.RefObject<HTMLDivElement | null>;
19	  nodeId: string;
20	  contentVersion: string;
21	  suspended: boolean;
22	}) {
23	  const { bodyRef, nodeId, contentVersion, suspended } = opts;
24	  const allNodes = useSessionStore((s) => s.nodes);
25	  const allNotes = useSessionStore((s) => s.notes);
26	  const setActiveNode = useSessionStore((s) => s.setActiveNode);
27	  const pendingScrollAnchor = useSessionStore((s) => s.pendingScrollAnchor);
28	  const clearScrollAnchor = useSessionStore((s) => s.clearScrollAnchor);
29	
30	  const childAnchors = useMemo(
31	    () =>
32	      Object.values(allNodes)
33	        .filter((c) => c.parentId === nodeId && c.parentAnchor?.selectedText)
34	        .map((c) => ({ text: c.parentAnchor!.selectedText, childId: c.id })),
35	    [allNodes, nodeId],
36	  );
37	  const noteAnchors = useMemo(
38	    () =>
39	      allNotes
40	        .filter((n) => n.sourceNodeId === nodeId)
41	        .map((n) => ({ text: n.quotedText, noteId: n.id })),
42	    [allNotes, nodeId],
43	  );
44	  // Stage 16: transient search anchor injected only while the user is
45	  // landing on this node from a search result. Cleared once clearScrollAnchor
46	  // runs (after the pulse fades or the selector misses twice).
47	  const searchAnchor = useMemo(() => {
48	    if (!pendingScrollAnchor) return null;
49	    if (pendingScrollAnchor.kind !== "search") return null;
50	    if (pendingScrollAnchor.nodeId !== nodeId) return null;
51	    // matchKind === "question" hits scroll to the QuestionBlock at the
52	    // top of the view by default — no DOM injection on this body needed.
53	    if (pendingScrollAnchor.matchKind === "question") return null;
54	    if (!pendingScrollAnchor.matchText) return null;
55	    return pendingScrollAnchor.matchText;
56	  }, [pendingScrollAnchor, nodeId]);
57	
58	  const onMarkClick = (e: React.MouseEvent) => {
59	    const target = (e.target as HTMLElement).closest("[data-child-id]");
60	    if (!target) return;
61	    const childId = target.getAttribute("data-child-id");
62	    if (!childId) return;
63	    e.preventDefault();
64	    e.stopPropagation();
65	    setActiveNode(childId);
66	  };
67	
68	  // Inject child + note <mark> on the rendered markdown DOM. Notes
69	  // first, child second → child marks land *inside* note marks
70	  // (visually amber inside emerald, which is what we want; click
71	  // routing via closest still works).
72	  useEffect(() => {
73	    if (suspended) return;
74	    const root = bodyRef.current;
75	    if (!root) return;
76	    clearMarks(root);
77	    const specs: MarkSpec[] = [];
78	    if (noteAnchors.length) {
79	      specs.push({
80	        dataKey: "noteId",
81	        anchors: noteAnchors.map((a) => ({ text: a.text, id: a.noteId })),
82	      });
83	    }
84	    if (childAnchors.length) {
85	      specs.push({
86	        dataKey: "childId",
87	        anchors: childAnchors.map((a) => ({ text: a.text, id: a.childId })),
88	      });
89	    }
90	    if (searchAnchor) {
91	      // One search hit at a time → fixed id "current". Pushed last so it
92	      // lands innermost (matches the note-vs-child layering convention).
93	      specs.push({
94	        dataKey: "searchId",
95	        anchors: [{ text: searchAnchor, id: "current" }],
96	      });
97	    }
98	    if (specs.length) injectMarks(root, specs);
99	    return () => {
100	      if (root) clearMarks(root);
101	    };
102	  }, [
103	    suspended,
104	    contentVersion,
105	    childAnchors,
106	    noteAnchors,
107	    searchAnchor,
108	    bodyRef,
109	  ]);
110	
111	  // Scroll-to-anchor: handles both child-id (jump-back-to-parent) and
112	  // note-id (jump-from-notebook). A single anchor may span multiple
113	  // <mark> elements (one per textNode it crossed during DOM injection);
114	  // querySelectorAll catches them all, scroll the first to center and
115	  // pulse all. We still wait an rAF for markdown commit + injection
116	  // effect, retrying once before clearing.
117	  useEffect(() => {
118	    if (!pendingScrollAnchor) return;
119	    if (pendingScrollAnchor.nodeId !== nodeId) return;
120	    if (suspended) return;
121	    const selector =
122	      pendingScrollAnchor.kind === "child"
123	        ? `mark[data-child-id="${CSS.escape(pendingScrollAnchor.childId)}"]`
124	        : pendingScrollAnchor.kind === "note"
125	          ? `mark[data-note-id="${CSS.escape(pendingScrollAnchor.noteId)}"]`
126	          : `mark[data-search-id="current"]`;
127	    let raf = 0;
128	    let timer = 0;
129	    raf = window.requestAnimationFrame(() => {
130	      const root = bodyRef.current;
131	      if (!root) return;
132	      const targets = root.querySelectorAll<HTMLElement>(selector);
133	      if (!targets.length) {
134	        raf = window.requestAnimationFrame(() => {
135	          const t2 = root.querySelectorAll<HTMLElement>(selector);
136	          if (t2.length) flash(t2);
137	          else clearScrollAnchor();
138	        });
139	        return;
140	      }
141	      flash(targets);
142	    });
143	    function flash(els: NodeListOf<HTMLElement>) {
144	      els[0].scrollIntoView({ block: "center", behavior: "smooth" });
145	      els.forEach((el) => el.classList.add("anchor-pulse"));
146	      timer = window.setTimeout(() => {
147	        els.forEach((el) => el.classList.remove("anchor-pulse"));
148	        clearScrollAnchor();
149	      }, 1500);
150	    }
151	    return () => {
152	      window.cancelAnimationFrame(raf);
153	      if (timer) window.clearTimeout(timer);
154	    };
155	  }, [pendingScrollAnchor, nodeId, suspended, clearScrollAnchor, bodyRef]);
156	
157	  return { onMarkClick };
158	}
