2	import { useEffect } from "react";
3	import { useSessionStore } from "@/stores/sessionStore";
4	import { isEditableTarget } from "@/lib/shortcuts";
5	import type { ChatNode } from "@/lib/types";
6	
7	// Global J / K → jump to next / previous unread node, in createdAt order.
8	// Wraps around. Skipped while typing in inputs / textareas / contentEditable.
9	// Cards on canvas auto-pan to the new active node (Canvas effect on
10	// activeNodeId); fullscreen view auto-loads the new active node. We don't
11	// auto-toggle fullScreen — staying in whichever layer the user picked.
12	//
13	// Vim convention (and Gmail / Twitter / Reddit): j = down/next, k = up/prev.
14	export function useUnreadNavigation() {
15	  useEffect(() => {
16	    const onKey = (e: KeyboardEvent) => {
17	      if (e.key !== "j" && e.key !== "J" && e.key !== "k" && e.key !== "K") {
18	        return;
19	      }
20	      if (e.metaKey || e.ctrlKey || e.altKey) return;
21	      if (isEditableTarget(e.target)) return;
22	      const direction: 1 | -1 = e.key === "j" || e.key === "J" ? 1 : -1;
23	      const store = useSessionStore.getState();
24	      const target = findNeighborUnread(
25	        store.nodes,
26	        store.activeNodeId,
27	        direction,
28	      );
29	      if (!target) return;
30	      e.preventDefault();
31	      store.setActiveNode(target);
32	    };
33	    window.addEventListener("keydown", onKey);
34	    return () => window.removeEventListener("keydown", onKey);
35	  }, []);
36	}
37	
38	function isUnreadNode(n: ChatNode): boolean {
39	  return n.status === "done" && !n.readAt;
